package com.wandertrace.controller;import com.wandertrace.dto.*;import com.wandertrace.dto.ContentDtos.*;import com.wandertrace.security.CurrentUser;import com.wandertrace.service.MediaService;import jakarta.servlet.http.HttpSession;import jakarta.validation.Valid;import java.io.IOException;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController public class MediaController {private final MediaService service;private final CurrentUser current;public MediaController(MediaService s,CurrentUser c){service=s;current=c;}private UUID user(HttpSession s){return current.require(s);}@GetMapping("/api/memories/{id}/media")ApiResponse<List<Media>>list(@PathVariable UUID id,HttpSession s){return ApiResponse.ok(service.list(user(s),id));}@PostMapping(value="/api/memories/{id}/media",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)@ResponseStatus(HttpStatus.CREATED)ApiResponse<Media>upload(@PathVariable UUID id,@RequestPart MultipartFile file,@RequestParam(required=false)String title,@RequestParam(required=false)String caption,@RequestParam(required=false)Integer sortOrder,HttpSession s)throws IOException{return ApiResponse.ok(service.upload(user(s),id,file,title,caption,sortOrder));}@PatchMapping("/api/media/{id}")ApiResponse<Media>update(@PathVariable UUID id,@Valid @RequestBody MediaMetadata r,HttpSession s){return ApiResponse.ok(service.update(user(s),id,r));}@DeleteMapping("/api/media/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable UUID id,HttpSession s)throws IOException{service.delete(user(s),id);}}
